import { API, graphqlOperation } from "aws-amplify";
import { update_list_email_templates } from "@/graphql/mutations.js";
import SnackBar from "@/components/SnackBar.vue";
import { VueEditor } from "vue3-editor";
export default {
  name: "OverdueTemplate",
  components: {
    SnackBar,
    VueEditor
  },
  data() {
    return {
      saving: false,
      isFormValid: false,
      windowHeight: 0,
      SnackBarComponent: {},
      // VueEditor properties
      customToolbar: [["bold", "italic", "underline", "strike"], ["blockquote", "code-block"], [{
        header: 1
      }, {
        header: 2
      }], [{
        list: "ordered"
      }, {
        list: "bullet"
      }], [{
        script: "sub"
      }, {
        script: "super"
      }], [{
        indent: "-1"
      }, {
        indent: "+1"
      }], [{
        direction: "rtl"
      }], [{
        size: ["small", false, "large", "huge"]
      }], [{
        header: [1, 2, 3, 4, 5, 6, false]
      }], [{
        color: []
      }, {
        background: []
      }], [{
        font: []
      }], [{
        align: []
      }], ["clean"], ["link", "image"]],
      editorOptions: {
        placeholder: "Enter email content...",
        theme: "snow"
      },
      // Template data
      templateName: "Overdue Payment Template",
      emailSubject: "Payment Overdue - {{invoice_number}}",
      emailContent: "Dear {{customer_name}},\n\nThis is a reminder that payment for invoice {{invoice_number}} is now overdue.\n\n**Overdue Details:**\n- Invoice Number: {{invoice_number}}\n- Invoice Date: {{invoice_date}}\n- Due Date: {{due_date}}\n- Days Overdue: {{days_overdue}}\n- Outstanding Amount: {{outstanding_amount}}\n- Late Fee: {{late_fee}}\n\n**Immediate Action Required:**\nPlease arrange payment immediately to avoid further late fees and potential service suspension.\n\n**Payment Options:**\n- Bank Transfer: {{bank_name}} - {{account_number}}\n- Online Payment: {{payment_link}}\n- Phone Payment: {{company_phone}}\n\n**Contact Information:**\nIf you have any questions or need to discuss payment arrangements, please contact us immediately.\n\nWe value your business and hope to resolve this matter promptly.\n\nBest regards,\n{{sender_name}}\n{{company_name}}",
      // Available variables for template
      availableVariables: [{
        key: "{{customer_name}}",
        label: "Customer Name"
      }, {
        key: "{{invoice_number}}",
        label: "Invoice Number"
      }, {
        key: "{{invoice_date}}",
        label: "Invoice Date"
      }, {
        key: "{{due_date}}",
        label: "Due Date"
      }, {
        key: "{{days_overdue}}",
        label: "Days Overdue"
      }, {
        key: "{{outstanding_amount}}",
        label: "Outstanding Amount"
      },
      // { key: "{{late_fee}}", label: "Late Fee" },
      // { key: "{{bank_name}}", label: "Bank Name" },
      // { key: "{{account_number}}", label: "Account Number" },
      // { key: "{{payment_link}}", label: "Payment Link" },
      // { key: "{{sender_name}}", label: "Sender Name" },
      {
        key: "{{company_name}}",
        label: "Company Name"
      }, {
        key: "{{company_address}}",
        label: "Company Address"
      }, {
        key: "{{company_phone}}",
        label: "Company Phone"
      }, {
        key: "{{company_email}}",
        label: "Company Email"
      }],
      quill: null
    };
  },
  mounted() {
    this.windowHeight = window.innerHeight - 150;
    this.loadTemplate();
  },
  methods: {
    async loadTemplate() {
      try {
        let result = await API.graphql(graphqlOperation(update_list_email_templates, {
          input: {
            action_type: "LIST",
            email_template_type: "OVER_DUE"
          }
        }));
        // console.log("Result:", result);
        let response = JSON.parse(result.data.update_list_email_templates);
        if (response.Status === "SUCCESS" && response.data.length > 0) {
          const emailTemplate = response.data[0].email_template;
          this.emailSubject = emailTemplate.subject || "";
          this.emailContent = emailTemplate.body || "";
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors?.[0]?.message || "Error fetching template",
          timeout: 5000,
          Top: true
        };
      }
    },
    goBack() {
      this.$emit("backAction");
    },
    onEditorReady(quill) {
      this.quill = quill;
    },
    onEditorInput(html) {
      this.emailContent = html;
    },
    insertVariable(variable) {
      if (this.quill) {
        const range = this.quill.getSelection();
        if (range) {
          this.quill.insertText(range.index, variable);
        } else {
          this.quill.insertText(this.quill.getLength(), variable);
        }
      }
    },
    async saveTemplate() {
      // Validate form before saving
      const {
        valid
      } = await this.$refs.templateForm.validate();
      if (!valid) {
        this.$toast?.error("Please fix validation errors before saving");
        return;
      }
      this.saving = true;
      try {
        let result = await API.graphql(graphqlOperation(update_list_email_templates, {
          input: {
            action_type: "UPDATE",
            email_template_type: "OVER_DUE",
            email_template: this.all_data_template()
          }
        }));
        let response = JSON.parse(result.data.update_list_email_templates);
        if (response.Status === "SUCCESS") {
          this.saving = false;
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors?.[0]?.message || "Error saving template",
          timeout: 5000,
          Top: true
        };
      } finally {
        this.saving = false;
      }
    },
    all_data_template() {
      var data = {
        body: this.emailContent,
        subject: this.emailSubject,
        cc: []
      };
      return JSON.stringify(data);
    }
  }
};
